import json
import itertools
from hypothesis import strategies as st

@st.composite
def gen(draw):
    nums = draw(st.one_of(
        st.lists(st.integers(1, 127), min_size=3, max_size=3),
        st.lists(st.sampled_from([1, 2, 3, 4, 7, 8, 15, 16, 64, 127]), min_size=3, max_size=3),
        st.just([1, 1, 1]),
        st.just([127, 127, 127]),
        st.just([1, 2, 4]),
    ))
    return json.dumps(nums)

def validate(inp):
    try:
        nums = json.loads(inp.strip())
    except Exception:
        return False
    if not isinstance(nums, list) or len(nums) != 3:
        return False
    for x in nums:
        if type(x) is not int or not (1 <= x <= 127):
            return False
    return True

def ref(inp):
    nums = json.loads(inp.strip())
    best = None
    for perm in itertools.permutations(nums):
        s = "".join(bin(x)[2:] for x in perm)
        v = int(s, 2)
        if best is None or v > best:
            best = v
    return json.dumps(best)
